import type { ErrorRequestHandler, Request, RequestHandler } from 'express';
import { z } from 'zod';
import {
  SourceNotFoundError,
  SourceSyncOffError,
} from '../../types/source-sync';
import type { BrowserSessions } from '../../library/BrowserSessions';
import {
  LibraryError,
  type LibraryErrorCode,
} from '../../services/libraryErrors';
import type {
  LibraryOperation,
  TelemetryService,
} from '../../services/TelemetryService';
import { errorMessage } from '../../utils/errorMessage';
import type { ErrorResponse } from '../../types/api-responses';

export const isLocalHost = (request: Request): boolean => {
  const port = request.socket.localPort;
  const host = request.headers.host;
  return (
    Boolean(port) &&
    (host === `localhost:${port}` || host === `127.0.0.1:${port}`)
  );
};

export const isLocalBrowserRequest = (request: Request): boolean =>
  isLocalHost(request) &&
  request.headers.origin === `http://${request.headers.host}`;

export const authenticateLibrary =
  (token: string, sessions?: BrowserSessions): RequestHandler =>
  (req, res, next) => {
    if (req.headers.origin && !isLocalBrowserRequest(req)) {
      res.sendStatus(403);
      return;
    }
    if (req.headers.authorization === `Bearer ${token}`) return next();
    const browserToken = req.headers.authorization?.match(/^Bearer (.+)$/)?.[1];
    if (
      !browserToken ||
      !sessions ||
      !isLocalHost(req) ||
      (req.method !== 'GET' &&
        req.method !== 'HEAD' &&
        !isLocalBrowserRequest(req))
    ) {
      res.sendStatus(401);
      return;
    }
    try {
      if (!sessions.isValid(browserToken)) {
        res.sendStatus(401);
        return;
      }
    } catch {
      res.status(503).json({
        error:
          'Browser authorization is unavailable. Please retry or sign in again.',
      } satisfies ErrorResponse);
      return;
    }
    next();
  };

const HANDLED_ERROR_KEY = 'libraryError';

export const trackLibraryOperation =
  (telemetry?: TelemetryService) =>
  (operation: LibraryOperation['operation']): RequestHandler =>
  (_req, res, next) => {
    const startedAt = Date.now();
    res.once('finish', () => {
      const isCompleted = res.statusCode < 400;
      telemetry?.trackLibraryOperation({
        operation,
        outcome: isCompleted ? 'completed' : 'failed',
        durationMs: Date.now() - startedAt,
        error: isCompleted ? undefined : res.locals[HANDLED_ERROR_KEY],
      });
    });
    next();
  };

const libraryErrorStatus = (code: LibraryErrorCode): number => {
  switch (code) {
    case 'project_not_found':
    case 'variant_not_found':
      return 404;
    case 'workspace_unavailable':
    case 'folder_picker_busy':
    case 'preview_unavailable':
      return 409;
    case 'folder_picker_unavailable':
      return 503;
    default: {
      const unhandled: never = code;
      throw new Error(`Unhandled library error: ${unhandled}`);
    }
  }
};

export const handleLibraryError: ErrorRequestHandler = (
  error: unknown,
  _req,
  res,
  _next,
) => {
  res.locals[HANDLED_ERROR_KEY] = error;
  const message = errorMessage(error);
  if (error instanceof LibraryError) {
    res
      .status(libraryErrorStatus(error.code))
      .json({ error: message } satisfies ErrorResponse);
    return;
  }
  if (error instanceof z.ZodError) {
    res.status(400).json({ error: message } satisfies ErrorResponse);
    return;
  }
  if (error instanceof SourceNotFoundError) {
    res.status(404).json({ error: message, code: error.code });
    return;
  }
  if (error instanceof SourceSyncOffError) {
    res.status(409).json({ error: message, code: error.code });
    return;
  }
  res.status(500).json({ error: message } satisfies ErrorResponse);
};
